use tauri_build::{AppManifest, Attributes};

// Every command the webview may call is declared here, so Tauri applies an
// ACL to it and the capability must allow it by name. An undeclared app
// command would be open to every window.
//
// tauri-build writes permissions/autogenerated/*.toml for these names and
// never deletes a stale one, and it reads every file there. So the files for
// the probe only commands (keychain_set, keychain_get, keychain_delete,
// probe_report) are not committed: they are git ignored and appear only when a
// probe build generates them, and `drop_stale_permissions` removes any file
// whose command is not in this build's list before tauri-build reads the
// folder, so a default build never carries a probe command in its ACL
// manifest (the webview holds no keychain command, item 4 review P2 1).
#[cfg(feature = "probe")]
const COMMANDS: &[&str] = &[
    "keychain_set",
    "keychain_get",
    "keychain_delete",
    "probe_report",
    "run_statement",
    "run_atomic",
    "auth_sign_in",
    "auth_resume",
    "auth_exchange",
    "auth_sign_out",
];
#[cfg(not(feature = "probe"))]
const COMMANDS: &[&str] =
    &["run_statement", "run_atomic", "auth_sign_in", "auth_resume", "auth_exchange", "auth_sign_out"];

fn drop_stale_permissions() {
    let Ok(entries) = std::fs::read_dir("permissions/autogenerated") else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if path.extension().is_some_and(|e| e == "toml") && !COMMANDS.contains(&stem) {
            let _ = std::fs::remove_file(&path);
        }
    }
}

fn main() {
    drop_stale_permissions();
    // The probe capability (open SQLite grant) sits in its own folder and is
    // read only when the probe feature is on, so a normal build never sees it.
    #[cfg(feature = "probe")]
    let pattern = "./capabilities*/*.json";
    #[cfg(not(feature = "probe"))]
    let pattern = "./capabilities/*.json";
    println!("cargo:rerun-if-changed=capabilities");
    println!("cargo:rerun-if-changed=capabilities-probe");
    tauri_build::try_build(
        Attributes::new()
            .app_manifest(AppManifest::new().commands(COMMANDS))
            .capabilities_path_pattern(pattern),
    )
    .expect("failed to run tauri-build");
}
